#!/usr/bin/env bash
# Generated-docs drift check -- the r329 lesson (`TODO` #358, closed by fixing it).
#
# WHY THIS EXISTS
#   `tools/cli/README.md`, `tools/completion/README.md` and `tools/server/README.md` are GENERATED by
#   `llama-gen-docs` from `common/arg.cpp`.  Every block that adds an option therefore owes a regeneration, and
#   nothing checked it: the r328 set shipped documents that predated blocks 06/09/12/13/14/15/16/0300, so a
#   consumer reading the delivered `tools/cli/README.md` could not see `--kv-window`, `-lme`, `-ib`,
#   `--wmma-verify`, `--spec-draft-mtp-vocab` or the `-ncmoe` LAST-N wording -- and a whole release went out
#   with the obligation recorded as "regenerate the docs" and silently skipped.
#
#   A regeneration is one command, so the failure mode is never "hard", it is "forgotten".  This check turns it
#   into a gate: run it on the tree you are about to cut/tag, after a build.
#
# USAGE
#   ./scripts/check-gen-docs.sh [repo] [--bin /path/to/llama-gen-docs]
#     repo    the llama.cpp checkout to check (default: ~/llama.cpp)
#     --bin   the generator built FROM THAT TREE (default: <repo>/build-rocm/bin/llama-gen-docs); must match
#             the tree, because it prints the help text of that tree's arg.cpp
#
# Exit: 0 = the committed docs already match `llama-gen-docs`; 1 = drift (the fix is to regenerate and fold the
# three files into the block that last touched `common/arg.cpp`); 2 = usage/prerequisite error.
set -uo pipefail

REPO="${1:-$HOME/llama.cpp}"
case "${1:-}" in -h|--help) sed -n '2,/^set -uo/p' "$0" | sed 's/^# \{0,1\}//; /^set -uo/d'; exit 0 ;; esac
[ -d "$REPO/.git" ] || { echo "ERROR: no git checkout at $REPO" >&2; exit 2; }
shift || true
BIN=""
while [ $# -gt 0 ]; do
    case "$1" in
        --bin) BIN="$2"; shift 2 ;;
        -h|--help) sed -n '2,/^set -uo/p' "$0" | sed 's/^# \{0,1\}//; /^set -uo/d'; exit 0 ;;
        *) echo "usage: $0 [repo] [--bin PATH]" >&2; exit 2 ;;
    esac
done
[ -n "$BIN" ] || BIN="$REPO/build-rocm/bin/llama-gen-docs"
[ -x "$BIN" ] || { echo "ERROR: no llama-gen-docs at $BIN (build it: cmake --build <build-dir> --target llama-gen-docs)" >&2; exit 2; }

DOCS=(tools/cli/README.md tools/completion/README.md tools/server/README.md)

if [ -n "$(git -C "$REPO" status --porcelain -- "${DOCS[@]}")" ]; then
    echo "ERROR: the tree already has changes in the generated docs; check a clean tree" >&2
    git -C "$REPO" status --short -- "${DOCS[@]}" >&2
    exit 2
fi

( cd "$REPO" && "$BIN" ) > /dev/null 2>&1 || { echo "ERROR: $BIN failed" >&2; exit 2; }

if [ -z "$(git -C "$REPO" status --porcelain -- "${DOCS[@]}")" ]; then
    echo "ok  generated docs match llama-gen-docs ($(basename "$BIN"), $(git -C "$REPO" rev-parse --short HEAD))"
    exit 0
fi

echo "FAIL  the committed generated docs are stale -- llama-gen-docs rewrites:"
git -C "$REPO" diff --stat -- "${DOCS[@]}" | sed 's/^/      /'
echo "      a block that adds an option owes a regeneration; fold the three files into the block that last"
echo "      touched common/arg.cpp (never the temporary 0300 -- it is dropped).  Reverting the tree:"
echo "        git -C $REPO checkout -- ${DOCS[*]}"
exit 1
